// Parse: !bug <summary> | <description>
const raw = ($json.body?.content ?? $json.content ?? '').trim();
const text = raw.replace(/^!(bug|task|issue)\s*/i, '');
const [summaryPart, ...descParts] = text.split('|');
const summary = (summaryPart || '').trim();
const description = descParts.join('|').trim();
const author = $json.body?.author?.username ?? 'unknown';
return { json: { summary, description, author } };
